import{_ as t,C as i,o as r,c as s,j as a,a as n,E as d,a0 as l}from"./chunks/framework.DwEC4Wzn.js";const _=JSON.parse('{"title":"下载与安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":null}'),c={name:"guide/install.md"};function p(h,e,u,w,P,k){const o=i("Downloads");return r(),s("div",null,[e[0]||(e[0]=a("h1",{id:"下载与安装",tabindex:"-1"},[n("下载与安装 "),a("a",{class:"header-anchor",href:"#下载与安装","aria-label":'Permalink to "下载与安装"'},"​")],-1)),d(o),e[1]||(e[1]=l('<h2 id="安装版" tabindex="-1">安装版 <a class="header-anchor" href="#安装版" aria-label="Permalink to &quot;安装版&quot;">​</a></h2><p>per-user 安装：装到 <code>%LOCALAPPDATA%\\Programs\\PowerKit</code>，全程不弹 UAC、不需要管理员权限。</p><ul><li>开始菜单会创建 PowerKit 项，桌面图标可选（默认不勾）；</li><li>卸载时一并清掉配置注册表 <code>HKCU\\Software\\PowerKit</code>、开机自启项与 <code>%APPDATA%\\PowerKit</code> 日志目录；</li><li>安装或卸载前请先从托盘退出正在运行的 PowerKit（程序占用会导致安装失败）。</li></ul><h2 id="便携版" tabindex="-1">便携版 <a class="header-anchor" href="#便携版" aria-label="Permalink to &quot;便携版&quot;">​</a></h2><p>解压后直接运行 <code>powerkit.exe</code> 即可，不写安装目录、不留卸载项；配置同样写在 <code>HKCU\\Software\\PowerKit</code>，所以便携版与安装版可以共用同一份设置。</p><h2 id="windows-on-arm" tabindex="-1">Windows on ARM <a class="header-anchor" href="#windows-on-arm" aria-label="Permalink to &quot;Windows on ARM&quot;">​</a></h2><p>ARM 机（骁龙 X / 8cx 等）请取包名带 <code>arm64</code> 的两份。ARM64 包的安装器本体是 x64 （Inno Setup 目前还不产出原生 ARM64 的 Setup.exe），在 ARM 机上经转译运行， 装进去的 <code>powerkit.exe</code> 是原生 ARM64。</p><h2 id="开机自启" tabindex="-1">开机自启 <a class="header-anchor" href="#开机自启" aria-label="Permalink to &quot;开机自启&quot;">​</a></h2><p>设置页 →「通用」勾选「开机自动启动」，程序会写入 <code>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run</code>；取消勾选即移除。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>自动限充依赖<strong>联想电源管理驱动</strong>：设备管理器 → 系统设备 → <code>Lenovo Power and Battery</code> （旧名 <code>Lenovo Power Manager</code>）。近年 ThinkPad（T / X / P / E 系列、部分 Legion）只要装过 Vantage 或联想电源管理驱动即可使用。</p><p>装好后运行一次自检，确认这台机器支持到什么程度（只读，不改任何设置）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">powerkit.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">selftest</span></span></code></pre></div><p>它会分别报告：充电阈值接口、亮度控制通道（WMI / DDC/CI）、前置摄像头、机器自带光线感应器。</p>',14))])}const f=t(c,[["render",p]]);export{_ as __pageData,f as default};
